mapper.select:
SELECT r.*, u.nickname AS userName, u.phone AS userPhone, o.patient_name AS patientName, o.patient_age AS patientAge, o.patient_gender AS patientGender, CASE o.patient_gender WHEN 0 THEN '女' WHEN 1 THEN '男' ELSE '未知' END AS patientGenderText, o.patient_phone AS patientPhone, d.name AS doctorName FROM report r LEFT JOIN orders o ON r.order_id = o.id LEFT JOIN user u ON r.user_id = u.id LEFT JOIN doctor d ON r.doctor_id = d.id
AND r.user_id = #{query.userId}
AND r.order_id = #{query.orderId}
AND r.status = #{query.status}
ORDER BY r.create_time DESC

